/**
 * @file Fields.ts
 * @brief Read and write engine fields by their catalog path.
 *
 * @details The engine catalog (`openswmm.engine.catalog` in Python) names every
 * property of the API by a dotted path such as `"node.max_depth"`,
 * `"link.stats.max_flow"` or `"climate.elevation"`. The Python bindings, the MCP
 * server and the gymnasium environments all address the engine this way. This
 * class gives TypeScript the same addressing for every catalog field that maps
 * onto a single C getter (and setter); the table is generated by
 * `tools/gen_fields.py` and verified against the native engine by
 * `tools/verify_fields_native.py`.
 *
 * ```ts
 * solver.fields.get("node.max_depth", "J1");      // 5
 * solver.fields.set("link.roughness", "C1", 0.012);
 * solver.fields.getAll("node.depth");              // one value per node
 * ```
 *
 * Values are in the model's units (see `describe(path).units`); enum fields
 * return their numeric value, Boolean fields `true`/`false`.
 *
 * @author   Caleb Buahin <caleb.buahin@gmail.com>
 * @copyright Copyright (c) 2026 Caleb Buahin. All rights reserved.
 * @license  Apache-2.0
 */

import { BadParamError, ElementNotFoundError, raiseForCode } from "./errors.js";
import { CATALOG_REVISION, ELEMENTS, FIELDS, type FieldSpec } from "./fields.generated.js";
import { rawOf, withCString, withDouble, withInt } from "./mem.js";
import type { OpenSwmmWasmModule } from "./types.js";

export type FieldValue = number | string | boolean;
type RawFn = (...args: unknown[]) => unknown;

/** Catalog-path access to engine fields (`solver.fields`). */
export class Fields {
  /** Catalog revision the field table was generated from. */
  static readonly catalogRevision = CATALOG_REVISION;

  private readonly _mod: OpenSwmmWasmModule;
  private readonly _handle: () => number;

  /** @internal */
  constructor(mod: OpenSwmmWasmModule, handle: () => number) {
    this._mod = mod;
    this._handle = handle;
  }

  /** Every field path this build can read, sorted. */
  paths(): string[] {
    return Object.keys(FIELDS).sort();
  }

  /** The C functions, type, units and description behind a field. */
  describe(path: string): FieldSpec {
    const spec = FIELDS[path];
    if (!spec) {
      const near = this.paths().filter((p) => p.split(".").pop() === path.split(".").pop());
      throw new BadParamError(
        `'${path}' is not a field reachable from TypeScript` +
          (near.length ? `; did you mean ${near.slice(0, 4).join(", ")}?` : ""),
      );
    }
    return spec;
  }

  /** Read a field; `element` (id or index) is required for per-element fields. */
  get(path: string, element?: string | number): FieldValue {
    const spec = this.describe(path);
    const head = this._head(spec, element);
    const fn = this._fn(spec.get);
    let value: FieldValue;
    switch (spec.kind) {
      case "num":
        value = withDouble(this._mod, (ptr) => fn(...head, ptr) as number);
        break;
      case "int":
        value = withInt(this._mod, (ptr) => fn(...head, ptr) as number);
        break;
      case "str":
        value = withCString(this._mod, 256, (buf, len) => fn(...head, buf, len) as number);
        break;
      default:
        value = (fn(...head) as string | null) ?? "";
    }
    return spec.type === "bool" ? value !== 0 : value;
  }

  /** Write a field; throws `BadParamError` for read-only fields. */
  set(path: string, element: string | number | undefined, value: FieldValue): void {
    const spec = this.describe(path);
    if (!spec.set) throw new BadParamError(`'${path}' is read-only`);
    const arg = typeof value === "boolean" ? (value ? 1 : 0) : value;
    if (spec.type === "str" ? typeof arg !== "string" : typeof arg !== "number")
      throw new BadParamError(`'${path}' takes a ${spec.type === "str" ? "string" : "number"}`);
    raiseForCode(this._fn(spec.set)(...this._head(spec, element), arg) as number);
  }

  /** Read a per-element field for every element, in index order. */
  getAll(path: string): FieldValue[] {
    const spec = this.describe(path);
    if (!spec.element) throw new BadParamError(`'${path}' is not a per-element field`);
    const count = this._fn(ELEMENTS[spec.element].count)(this._handle()) as number;
    return Array.from({ length: count }, (_, i) => this.get(path, i));
  }

  private _head(spec: FieldSpec, element: string | number | undefined): unknown[] {
    const handle = this._handle();
    if (!spec.element) {
      if (element !== undefined) throw new BadParamError("This field belongs to no element");
      return [handle];
    }
    if (element === undefined) throw new BadParamError(`'${spec.element}' id or index required`);
    if (typeof element === "number") return [handle, element];
    const index = this._fn(ELEMENTS[spec.element].index)(handle, element) as number;
    if (index < 0) throw new ElementNotFoundError(element, `No ${spec.element} '${element}'`);
    return [handle, index];
  }

  private _fn(name: string): RawFn {
    return (rawOf(this._mod) as unknown as Record<string, RawFn>)[name];
  }
}
